import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type FieldPart =
  | "root"
  | "label"
  | "requiredIndicator"
  | "control"
  | "helperText"
  | "errorText";

export const anatomy: Anatomy<FieldPart> = createAnatomy("field").parts(
  "root",
  "label",
  "requiredIndicator",
  "control",
  "helperText",
  "errorText",
);

export const parts: Record<FieldPart, AnatomyPart> = anatomy.build();

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./field.anatomy";
import { getControlId, getErrorTextId, getHelperTextId, getLabelId, getRootId } from "./field.dom";
import type { FieldApi, FieldControlProps, FieldSchema } from "./field.types";

export function connect<T extends PropTypes>(
  service: Service<FieldSchema>,
  normalize: NormalizeProps<T>,
): FieldApi<T> {
  const { context, prop, scope } = service;

  const invalid = prop("invalid");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const required = prop("required");
  const group = prop("group");

  const stateAttrs = {
    "data-invalid": dataAttr(invalid),
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-required": dataAttr(required),
  };

  // Only ids that exist, and the error first: a screen reader reads them in the
  // order they are listed, and what is wrong matters more than what was advised.
  const describedBy =
    [
      invalid && context.get("hasErrorText") ? getErrorTextId(scope) : null,
      context.get("hasHelperText") ? getHelperTextId(scope) : null,
    ]
      .filter((id) => id !== null)
      .join(" ") || undefined;

  const labelId = context.get("hasLabel") ? getLabelId(scope) : undefined;

  const controlProps: FieldControlProps = {
    id: getControlId(scope),
    "aria-describedby": describedBy,
    "aria-invalid": ariaAttr(invalid),
    disabled,
    readOnly,
    required,
  };

  return {
    invalid,
    disabled,
    required,
    readOnly,
    controlProps,
    labelId,

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir: prop("dir"),
        role: group ? "group" : undefined,
        // A group labels itself through its own label; a single field labels its
        // control, and the control is what carries the name. Only once that label
        // is really rendered — a group without one would name itself after an id
        // that is in no document.
        "aria-labelledby": group ? labelId : undefined,
      }),

    getLabelProps: (): T["label"] =>
      normalize.label({
        ...parts.label.attrs,
        ...stateAttrs,
        id: getLabelId(scope),
        // `for` only when there is a single control to point at — on a group it
        // would name one member and hide the rest — and only when that control is
        // something a label may name. A `div[role="slider"]` is not: the thumb
        // reads `labelId` back through `aria-labelledby` instead.
        for: group || !context.get("hasLabelableControl") ? undefined : getControlId(scope),
      }),

    getRequiredIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.requiredIndicator.attrs,
        // The control already says `required`; the asterisk is decoration, and
        // announcing "star" after every label is noise.
        "aria-hidden": ariaAttr(true),
        hidden: !required,
      }),

    getHelperTextProps: (): T["element"] =>
      normalize.element({ ...parts.helperText.attrs, ...stateAttrs, id: getHelperTextId(scope) }),

    getErrorTextProps: (): T["element"] =>
      normalize.element({
        ...parts.errorText.attrs,
        ...stateAttrs,
        id: getErrorTextId(scope),
        // Not a live region: it is a `aria-describedby` target, and the
        // announcement goes through the shared announcer instead (see
        // `announceError`). Making this element live *and* describing the
        // control with it would also have it read twice.
        hidden: !invalid,
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "field";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getHelperTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "helperText");
}

export function getErrorTextId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "errorText");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/** `aria-describedby` may only point at ids that exist, so presence is a fact to read. */
export function hasPart(scope: Scope, part: string): boolean {
  return query(getRootEl(scope), `[data-part~="field:${part}"]`) !== null;
}

const LABELABLE = ["BUTTON", "INPUT", "METER", "OUTPUT", "PROGRESS", "SELECT", "TEXTAREA"];

/**
 * Whether the control id landed on an element `<label for>` can actually name.
 *
 * A control that is a `div[role]` — the slider's thumb, for one — never takes the
 * id, and a control that takes it on a wrapper is not labelable either; both leave
 * `for` pointing at nothing and the label dead to the pointer. Read from the DOM
 * for the same reason the helper and error texts are: only the markup knows.
 *
 * Answers `true` before the first sync so a server-rendered field emits `for`
 * exactly as it does today — the correction lands with the first observation,
 * which runs after mount, when "no element has this id" is finally meaningful.
 */
export function hasLabelableControl(scope: Scope): boolean {
  const control = scope.getById(getControlId(scope));
  return control !== null && LABELABLE.includes(control.tagName);
}

/**
 * The accessibility hub of every form control: one place that owns the label's
 * id, the description ids, and the three states — invalid, disabled, required —
 * that a control and its text have to agree on.
 *
 * The only thing it needs a machine for is presence. `aria-describedby` may only
 * point at ids that exist: a field that always described itself as having an
 * error message would fail validation the moment the message was not rendered.
 * So whether the helper and error texts are in the DOM is read from the DOM, and
 * re-read when the children change.
 */

import { getLiveAnnouncer } from "../../a11y/live-announcer";
import { observeChildren } from "../../dom/observers";
import { query } from "../../dom/query";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getRootEl, hasLabelableControl, hasPart } from "./field.dom";
import type { FieldSchema } from "./field.types";

export const machine: Machine<FieldSchema> = createMachine<FieldSchema>({
  props({ props }) {
    return {
      invalid: false,
      disabled: false,
      readOnly: false,
      required: false,
      group: false,
      ...props,
    };
  },

  context({ bindable }) {
    return {
      hasHelperText: bindable<boolean>(() => ({ defaultValue: false })),
      hasErrorText: bindable<boolean>(() => ({ defaultValue: false })),
      hasLabel: bindable<boolean>(() => ({ defaultValue: false })),
      // The one default that is not `false`: see `hasLabelableControl`.
      hasLabelableControl: bindable<boolean>(() => ({ defaultValue: true })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackParts"],

  watch({ prop, scope, track, action }) {
    // A dependency like any other, so an adapter that re-renders is in step
    // immediately rather than one mutation record later.
    track(
      () => [
        hasPart(scope, "helper-text"),
        hasPart(scope, "error-text"),
        hasPart(scope, "label"),
        hasLabelableControl(scope),
      ],
      () => action(["syncParts"]),
    );
    track(
      () => [prop("invalid")],
      () => action(["announceError"]),
    );
  },

  on: {
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    actions: {
      syncParts({ context, scope }) {
        context.set("hasHelperText", hasPart(scope, "helper-text"));
        context.set("hasErrorText", hasPart(scope, "error-text"));
        context.set("hasLabel", hasPart(scope, "label"));
        context.set("hasLabelableControl", hasLabelableControl(scope));
      },

      /**
       * Announced through the shared announcer rather than by making the error
       * element a live region. A live region that is `hidden` until it has
       * something to say is not registered while hidden, so it appears already
       * populated — and a region that appears with its content is the classic
       * way to be announced by nobody. The announcer's regions are created empty
       * up front and written on a later task, which is the whole point of it.
       */
      announceError({ prop, scope }) {
        if (!prop("invalid")) return;
        const message =
          query(getRootEl(scope), '[data-part~="field:error-text"]')?.textContent ?? "";
        if (message.trim() === "") return;
        getLiveAnnouncer(scope.getDoc()).announce(message, "polite");
      },
    },

    effects: {
      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        return observeChildren(getRootEl(scope), () => send({ type: "PARTS.SYNC" }));
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction } from "../../types";

export interface FieldMachineProps {
  readonly dir?: Direction | undefined;
  readonly invalid?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly required?: boolean | undefined;
  /** Groups (`fieldset`/`legend`) instead of a single labelled control. */
  readonly group?: boolean | undefined;
}

export interface ResolvedFieldMachineProps extends FieldMachineProps {
  readonly invalid: boolean;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly group: boolean;
}

export interface FieldSchema extends MachineSchema {
  state: "idle";
  props: ResolvedFieldMachineProps;
  /**
   * Whether the optional parts are actually rendered, and whether the control id
   * reached something `for` may name — all read from the DOM.
   */
  context: {
    hasHelperText: boolean;
    hasErrorText: boolean;
    hasLabel: boolean;
    hasLabelableControl: boolean;
  };
  event: { type: "PARTS.SYNC" };
  action: "syncParts" | "announceError";
  effect: "trackParts";
}

/** What a control merges to be wired into the field. */
export interface FieldControlProps {
  readonly id: string;
  readonly "aria-describedby": string | undefined;
  readonly "aria-invalid": "true" | undefined;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
}

export interface FieldApi<T extends PropTypes = PropTypes> {
  readonly invalid: boolean;
  readonly disabled: boolean;
  readonly required: boolean;
  readonly readOnly: boolean;
  /** The ids and states any control in this field has to carry. */
  readonly controlProps: FieldControlProps;
  /**
   * The label's id, for a control that `<label for>` cannot name and that has to
   * point back with `aria-labelledby` instead. `undefined` while no label part is
   * rendered — an `aria-labelledby` at a missing id names nothing and fails audit.
   */
  readonly labelId: string | undefined;
  getRootProps(): T["element"];
  getLabelProps(): T["label"];
  getRequiredIndicatorProps(): T["element"];
  getHelperTextProps(): T["element"];
  getErrorTextProps(): T["element"];
}

export { anatomy, type FieldPart, parts } from "./field.anatomy";
export { connect } from "./field.connect";
export {
  getControlId,
  getErrorTextId,
  getHelperTextId,
  getLabelId,
  getRootEl,
  getRootId,
} from "./field.dom";
export { machine } from "./field.machine";
export type {
  FieldApi,
  FieldControlProps,
  FieldMachineProps,
  FieldSchema,
  ResolvedFieldMachineProps,
} from "./field.types";

/**
 * `<Field>` — the composed layer around a single control, or a group of them: a
 * label, its required indicator, the control itself, then the field's own
 * messages. `children` is the control — an `InputRoot`, a `RadioGroupRoot`,
 * anything that reads the field context for its own scope — because a field
 * without a control is the part every other composed layer nests inside.
 *
 * There is no `FieldControl` part to place here: `field/index.ts` never exported
 * one, because the anatomy's `control` is not a node the field renders — it is
 * `controlProps`, merged into whatever the consumer puts inside. `children` is
 * that placement in the composed vocabulary.
 *
 * `group` picks the label part, not just an attribute: a group's caption is a
 * `<legend>` (`FieldLegend`), a single control's is a `<label>` (`FieldLabel`),
 * and the two are different components rather than one element with a flag —
 * the same fork `FieldRoot` already makes for `fieldset`/`div`.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  FieldErrorText,
  FieldHelperText,
  FieldLabel,
  FieldLegend,
  FieldRequiredIndicator,
  FieldRoot,
  type UseFieldProps,
} from "./field";

export interface FieldComposedProps
  extends UseFieldProps,
    Omit<PartProps<"div", UseFieldProps>, "children"> {
  /** The control this field names and describes. */
  readonly children?: ReactNode;
  readonly label?: ReactNode;
  /** Shown beside the label while `required` is true. Defaults to `"*"`. */
  readonly requiredIndicator?: ReactNode;
  readonly helperText?: ReactNode;
  readonly errorText?: ReactNode;
}

export function Field(props: FieldComposedProps): ReactNode {
  const { children, label, requiredIndicator, helperText, errorText, ...rest } = props;
  const Label = rest.group === true ? FieldLegend : FieldLabel;

  return (
    <FieldRoot {...rest}>
      {label == null ? null : (
        <Label>
          {label}
          {rest.required === true ? (
            <FieldRequiredIndicator>{requiredIndicator ?? "*"}</FieldRequiredIndicator>
          ) : null}
        </Label>
      )}
      {children}
      {helperText == null ? null : <FieldHelperText>{helperText}</FieldHelperText>}
      {errorText == null ? null : <FieldErrorText>{errorText}</FieldErrorText>}
    </FieldRoot>
  );
}

import * as field from "@standarui/core/field";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { FieldContext as SharedFieldContext, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type FieldApi = field.FieldApi<ReactPropTypes>;

const FieldContext = SharedFieldContext;

export interface UseFieldProps extends field.FieldMachineProps, MachineRuntimeProps {}

export function useField(props: UseFieldProps): FieldApi {
  return field.connect(useMachine(field.machine, props), normalizeProps);
}

export { useFieldContext };

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "invalid",
  "disabled",
  "readOnly",
  "required",
  "group",
] as const;

export interface FieldRootProps extends UseFieldProps, PartProps<"div", UseFieldProps> {}

export function FieldRoot(props: FieldRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useField(machineProps);

  return (
    <FieldContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        // A group of controls is a `<fieldset>`; a single labelled control is a
        // `<div>`, because a fieldset around one input is noise to a screen
        // reader.
        element: machineProps.group === true ? "fieldset" : "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </FieldContext.Provider>
  );
}

export const FieldLabel: (props: PartProps<"label">) => ReactNode = createPart(FieldContext, {
  name: "FieldLabel",
  element: "label",
  props: (api) => api.getLabelProps(),
});

/** A `<legend>` when the field is a group — the label a fieldset understands. */
export const FieldLegend: (props: PartProps<"legend">) => ReactNode = createPart(FieldContext, {
  name: "FieldLegend",
  element: "legend",
  props: (api) => api.getLabelProps(),
});

export const FieldRequiredIndicator: (props: PartProps<"span">) => ReactNode = createPart(
  FieldContext,
  {
    name: "FieldRequiredIndicator",
    element: "span",
    props: (api) => api.getRequiredIndicatorProps(),
  },
);

export const FieldHelperText: (props: PartProps<"span">) => ReactNode = createPart(FieldContext, {
  name: "FieldHelperText",
  element: "span",
  props: (api) => api.getHelperTextProps(),
});

export const FieldErrorText: (props: PartProps<"span">) => ReactNode = createPart(FieldContext, {
  name: "FieldErrorText",
  element: "span",
  props: (api) => api.getErrorTextProps(),
});

export type { FieldControlProps, FieldMachineProps } from "@standarui/core/field";
export { Field, type FieldComposedProps } from "./composed";
export {
  type FieldApi,
  FieldErrorText,
  FieldHelperText,
  FieldLabel,
  FieldLegend,
  FieldRequiredIndicator,
  FieldRoot,
  type FieldRootProps,
  type UseFieldProps,
  useField,
  useFieldContext,
} from "./field";
